package com.example.code.data

import com.example.code.model.Lottery
import com.example.code.model.LotteryCampsite
import org.junit.Assert.*
import org.junit.Test

class LotteryUpdateMappingTest {
    private val lottery = Lottery(
        id = "lottery-1", ownerId = "owner-1", campsiteId = "site-1", campsiteName = "Pine Creek",
        registrationStart = 1_000L, registrationEnd = 2_000L,
        bookingStart = 3_000L, bookingEnd = 4_000L, winnerCount = 2,
        waitlistCapacity = 10, waitingListCount = 7, winnerIds = listOf("retained-winner"),
    )
    @Test fun onlyEditableFieldsAreWritten() {
        val fields = lotteryUpdateToMap(lottery)
        assertEquals(setOf("campsiteId", "campsiteName", "campsites", "registrationStart",
            "registrationEnd", "bookingStart", "bookingEnd", "winnerCount", "waitlistCapacity"), fields.keys)
        for (protected in listOf("id", "ownerId", "status", "waitingListCount", "winnerIds", "drawnAt")) {
            assertFalse(protected, fields.containsKey(protected))
        }
        assertEquals(2, fields["winnerCount"])
        assertEquals(2_000L, fields["registrationEnd"])
    }
    @Test fun unlimitedCapacityIsExplicitlyCleared() {
        val fields = lotteryUpdateToMap(lottery.copy(waitlistCapacity = null))
        assertTrue(fields.containsKey("waitlistCapacity"))
        assertNull(fields["waitlistCapacity"])
    }
    @Test fun reducingToSingleSiteExplicitlyClearsOldGroupArray() {
        assertEquals(emptyList<Map<String, String>>(), lotteryUpdateToMap(lottery)["campsites"])
    }
    @Test fun multipleSiteNamesAndIdsAreMapped() {
        val sites = listOf(LotteryCampsite("site-1", "Pine Creek"), LotteryCampsite("site-2", "River Bend"))
        assertEquals(sites.map { mapOf("id" to it.id, "name" to it.name) },
            lotteryUpdateToMap(lottery.copy(campsites = sites))["campsites"])
    }
}
